using System;
using System.IO;
using System.Text;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace PickDoll.Editor {
 public static class WeekTwelveDiagnostics {
  public static void ValidateChute(){var previous=Physics.simulationMode;var report=new StringBuilder();bool passed=true;try{Physics.simulationMode=SimulationMode.Script;for(int index=0;index<7;index++)foreach(bool lying in new[]{false,true}){EditorSceneManager.OpenScene(WeekTwelveBuilder.ScenePath);var c=UnityEngine.Object.FindAnyObjectByType<ClawCycle>();c.receiver.persistentProgress=false;c.Initialize();for(int j=0;j<7;j++){c.prizes[j].isKinematic=true;c.prizes[j].position=new Vector3(5+j,1,5);}var body=c.prizes[index];body.isKinematic=false;body.rotation=Quaternion.Euler(lying?90:0,0,0);var shape=PrizeStock.BoundsAt(body,Vector3.zero,body.rotation);body.position=new Vector3(-.23f-shape.center.x,.46f,-.25f-shape.center.z);body.linearVelocity=body.angularVelocity=Vector3.zero;Physics.SyncTransforms();bool cleared=false;int step=0;for(;step<800;step++){Physics.Simulate(.01f);if(body.position.z<-.90f&&body.position.y<.30f){cleared=true;break;}}passed&=cleared;report.AppendLine(index+" lying="+lying+" cleared="+cleared+" seconds="+(step*.01f)+" pos="+body.position);}Directory.CreateDirectory("Builds/Week12/Checks");File.WriteAllText("Builds/Week12/Checks/chute-geometry.txt",(passed?"PASS\n":"FAIL\n")+report);if(!passed)throw new Exception("Chute geometry failed: "+report);Debug.Log("PICKDOLL_WEEK12_CHUTE_GEOMETRY_PASS");}finally{Physics.simulationMode=previous;EditorSceneManager.OpenScene(WeekTwelveBuilder.ScenePath);}}
  // Gravity-only editor simulation: contact callbacks and acquisition are checked in the player.
  public static void ValidateStability(){var previous=Physics.simulationMode;var report=new StringBuilder();try{Physics.simulationMode=SimulationMode.Script;foreach(int index in new[]{3,4,6})foreach(bool lying in new[]{false,true}){EditorSceneManager.OpenScene(WeekTwelveBuilder.ScenePath);var c=UnityEngine.Object.FindAnyObjectByType<ClawCycle>();c.receiver.persistentProgress=false;c.Initialize();for(int j=0;j<7;j++)if(j!=index){c.prizes[j].isKinematic=true;c.prizes[j].position=new Vector3(5+j,1,5);}var body=c.prizes[index];var pose=lying?Quaternion.Euler(90,0,0):Quaternion.identity;body.isKinematic=false;body.rotation=pose;body.position=new Vector3(.17f,.645f-PrizeStock.BoundsAt(body,Vector3.zero,pose).min.y,.16f);body.linearVelocity=body.angularVelocity=Vector3.zero;Physics.SyncTransforms();for(int step=0;step<180;step++)Physics.Simulate(.01f);float upright=Mathf.Abs(Vector3.Dot(body.rotation*Vector3.up,Vector3.up));bool ok=lying?upright<.55f:upright>.95f;report.AppendLine($"{index} lying={lying} stable={ok} vertical={upright:F3} pos={body.position}");if(!ok)throw new Exception("Plush resting pose unstable: "+report);}Directory.CreateDirectory("Builds/Week12/Checks");File.WriteAllText("Builds/Week12/Checks/stability.txt","PASS\n"+report);}finally{Physics.simulationMode=previous;EditorSceneManager.OpenScene(WeekTwelveBuilder.ScenePath);}}
 }
}
